// Helper to fully enrich all 212 raw products
window.getEnrichedProducts = function() {
  if (window._ENRICHED_CACHE) return window._ENRICHED_CACHE;

  const raw = window.PRODUCTS || [];

  const enriched = raw.map((p, index) => {
    // 1. Determine category matching
    const titleLower = p.title.toLowerCase();
    let matchedCat = window.CATEGORIES_DATA.find(c =>
      c.keywords.some(k => titleLower.includes(k.toLowerCase()))
    );

    if (!matchedCat) {
      // Fallback categorization based on item ranges or titles
      if (titleLower.includes('mandir')) matchedCat = window.CATEGORIES_DATA.find(c => c.id === 'wooden-mandirs');
      else if (titleLower.includes('mala')) matchedCat = window.CATEGORIES_DATA.find(c => c.id === 'malas-rudraksha');
      else if (titleLower.includes('frame') || titleLower.includes('photo')) matchedCat = window.CATEGORIES_DATA.find(c => c.id === 'photo-frames');
      else if (titleLower.includes('diya') || titleLower.includes('lamp') || titleLower.includes('deepam')) matchedCat = window.CATEGORIES_DATA.find(c => c.id === 'diyas-lamps');
      else if (titleLower.includes('idol') || titleLower.includes('statue')) matchedCat = window.CATEGORIES_DATA.find(c => c.id === 'god-idols');
      else matchedCat = window.CATEGORIES_DATA[3]; // Pooja Samagri default
    }

    // 2. Consistent deterministic price calculation based on ID
    const numId = parseInt(p.id.replace('product_', '')) || (index + 1);
    let basePrice = 249;

    switch (matchedCat.id) {
      case 'god-idols':
        basePrice = 499 + ((numId * 87) % 3500);
        break;
      case 'diyas-lamps':
        basePrice = 149 + ((numId * 43) % 850);
        break;
      case 'photo-frames':
        basePrice = 349 + ((numId * 51) % 1150);
        break;
      case 'wooden-mandirs':
        basePrice = 2499 + ((numId * 133) % 7500);
        break;
      case 'brass-items':
        basePrice = 299 + ((numId * 67) % 1700);
        break;
      case 'malas-rudraksha':
        basePrice = 199 + ((numId * 37) % 600);
        break;
      case 'decor-garlands':
        basePrice = 149 + ((numId * 31) % 450);
        break;
      case 'incense-dhoop':
        basePrice = 69 + ((numId * 19) % 250);
        break;
      case 'festival-kits':
        basePrice = 699 + ((numId * 79) % 1800);
        break;
      default:
        basePrice = 99 + ((numId * 29) % 350);
    }

    // Round to standard Indian e-commerce prices ending in 9 or 0
    const price = Math.round(basePrice / 10) * 10 - 1;
    // MRP is typically 20% to 40% higher
    const discountPct = 15 + (numId % 25); // 15% - 39%
    const mrp = Math.round((price / (1 - discountPct / 100)) / 10) * 10;
    const rating = (4.3 + ((numId % 7) * 0.1)).toFixed(1);
    const reviewCount = 18 + ((numId * 13) % 280);

    // Stock rule: Photo frames are ALWAYS in stock; others 90% in stock
    const inStock = matchedCat.id === 'photo-frames' ? true : (numId % 10 !== 0);
    const stockQty = inStock ? (5 + (numId % 20)) : 0;

    // Badges
    let badge = null;
    if (numId % 8 === 1) badge = "Bestseller";
    else if (numId % 8 === 2) badge = "Festive Deal";
    else if (numId % 8 === 3) badge = "Temple Grade";
    else if (numId % 8 === 4) badge = "Trending";

    // Rich Specifications
    let material = "Pure Solid Brass";
    if (matchedCat.id === 'photo-frames') material = "Teak Finish Frame & Gold Foil";
    else if (matchedCat.id === 'malas-rudraksha') material = titleLower.includes('tulsi') ? "Sacred Holy Tulsi Wood" : "Natural Panchamukhi Rudraksha";
    else if (matchedCat.id === 'decor-garlands') material = "High Grade Silk & Marigold Fibers";
    else if (matchedCat.id === 'wooden-mandirs') material = "Treated Sheesham Wood & Brass Accents";
    else if (matchedCat.id === 'pooja-samagri') material = "100% Pure & Natural Sacred Ingredients";

    const dimensions = `${8 + (numId % 15)} cm x ${6 + (numId % 10)} cm`;
    const weight = `${150 + ((numId * 25) % 1200)} grams`;

    // Descriptions
    const descriptions = [
      `Authentic sacred ${p.title} handpicked for daily temple rituals and home mandirs. Brings auspicious positive energy, prosperity, and peace into your living spaces. Sourced directly with quality assurance by 7 Hills Pooja Store, LB Nagar.`,
      `Exquisitely crafted ${p.title} created following traditional Agamic and Vedic artisan techniques. Designed for enduring divine beauty and longevity during sacred worship.`,
      `Bring home the divine blessings of Tirumala with this genuine ${p.title}. Blessed and prepared in accordance with traditional spiritual practices.`,
      `Hand-finished ${p.title} with rich detailing. Ideal for housewarming ceremonies (Gruhapravesam), wedding return gifts, Diwali, and festive poojas.`
    ];
    const description = descriptions[numId % descriptions.length];

    const ritualUsage = [
      "Light with pure cow ghee or sesame oil during morning and evening sandhya pooja.",
      "Place upon an elevated wooden chowki facing East or North for maximum spiritual harmony.",
      "Apply sacred sandal paste (chandanam) and kumkum prior to chanting auspicious mantras.",
      "Clean with brasso or natural pitambari powder for everlasting radiant golden shine."
    ][numId % 4];

    return {
      ...p,
      category: matchedCat.name,
      categoryId: matchedCat.id,
      categoryIcon: matchedCat.icon,
      price,
      mrp,
      discount: discountPct,
      rating: parseFloat(rating),
      reviewCount,
      inStock,
      stockQty,
      badge,
      description,
      specifications: {
        "Material": material,
        "Dimensions (approx)": dimensions,
        "Net Weight": weight,
        "Country of Origin": "India (Handcrafted)",
        "Spiritual Significance": "Positive Energy & Auspicious Harmony",
        "Recommended Care": "Clean with dry soft cotton cloth; avoid harsh detergents."
      },
      ritualUsage,
      // Related products helper
      relatedIds: [
        `product_${((index + 1) % raw.length) + 1}`,
        `product_${((index + 2) % raw.length) + 1}`,
        `product_${((index + 3) % raw.length) + 1}`,
        `product_${((index + 4) % raw.length) + 1}`
      ]
    };
  });

  window._ENRICHED_CACHE = enriched;
  return enriched;
};
